import { useEffect, useState } from "react";

/**
 * Hook to load external script.
 * @param src - Source url to load.
 * @param onLoad - Success callback.
 * @param onError - Error callback.
 */
export function useLoadScript(src: string) {
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const [isSuccess, setIsSuccess] = useState(false);
  const onLoad = () => {
    setIsLoading(false);
    setIsSuccess(true);
  };
  useEffect(() => {
    if (!document) {
      const error = new Error(
        `[ScriptLoadingError] document not defined when attempting to load ${src}`,
      );
      setError(error);
      return;
    }

    // Find script tag with same src in DOM.
    const foundScript = document.querySelector<HTMLScriptElement>(
      `script[src="${src}"]`,
    );

    // Call onLoad if script marked as loaded.
    if (foundScript?.dataset.loaded) {
      onLoad();
      return;
    }

    // Create or get existed tag.
    const script = foundScript || document.createElement("script");

    // Set src if no script was found.
    if (!foundScript) {
      script.src = src;
    }

    // Mark script as loaded on load event.
    const onLoadWithMarker = () => {
      script.dataset.loaded = "1";
      onLoad();
    };

    script.addEventListener("load", onLoadWithMarker);

    script.addEventListener("error", (err) => {
      console.error("Failed to load script:", src, err);
      const error = new Error(
        `[ScriptLoadingError] Failed to load script: ${src}`,
      );
      setError(error);
    });

    // Add to DOM if not yet added.
    if (!foundScript) {
      document.head.append(script);
    }
  }, []);
  return {
    isLoading,
    error,
    isSuccess,
  };
}
import { useState, useEffect } from "react";
import {
  GoogleChartVersion,
  GoogleChartPackages,
  GoogleViz,
  ReactGoogleChartProps,
} from "../types";
import { useLoadScript } from "./useLoadScript";

export interface IUseLoadGoogleChartsParams {
  chartVersion?: GoogleChartVersion;
  chartPackages?: GoogleChartPackages[];
  chartLanguage?: string;
  mapsApiKey?: string;
}

const isGoogleReady = (google?: GoogleViz) => {
  return google && google.charts;
};

const isGoogleChartsReady = (
  props: ReactGoogleChartProps,
  google?: GoogleViz,
) => {
  const { controls, toolbarItems, getChartEditor } = props;
  return (
    google &&
    google.charts &&
    google.visualization &&
    google.visualization.ChartWrapper &&
    google.visualization.Dashboard &&
    (!controls || google.visualization.ChartWrapper) &&
    (!getChartEditor || google.visualization.ChartEditor) &&
    (!toolbarItems || google.visualization.drawToolbar)
  );
};

const getGoogleInstanceFromWindow = (props: ReactGoogleChartProps) => {
  // @ts-expect-error Getting object from global namespace.
  const google = window.google as GoogleViz;
  return google;
};

/**
 * Hook to load Google Charts JS API.
 * @param params - Load parameters.
 * @param [params.chartVersion] - Chart version to load.
 * @param [params.chartPackages] - Packages to load.
 * @param [params.chartLanguage] - Languages to load.
 * @param [params.mapsApiKey] - Google Maps api key.
 * @returns
 */
export function useLoadGoogleCharts(props: ReactGoogleChartProps) {
  const {
    chartVersion = "current",
    chartPackages = ["corechart", "controls"],
    chartLanguage = "en",
    mapsApiKey,
  } = props;
  const [googleCharts, setGoogleCharts] = useState<GoogleViz | null>(null);
  const [scriptInitializationError, setScriptInitializationError] =
    useState<Error | null>(null);
  const [googleChartsInitializationError, setGoogleChartsInitializationError] =
    useState<Error | null>(null);
  const {
    isLoading,
    error: scriptLoadingError,
    isSuccess,
  } = useLoadScript(
    props.chartLoaderScriptUrl || "https://www.gstatic.com/charts/loader.js",
  );

  useEffect(() => {
    if (!isSuccess) {
      return;
    }
    const google = getGoogleInstanceFromWindow(props);
    if (!isGoogleReady(google)) {
      const error = new Error(
        "[ScriptInitializationError] Script loaded but Google not attached to window.",
      );
      setScriptInitializationError(error);
      return;
    }
    if (isGoogleChartsReady(props, google)) {
      setGoogleCharts(google);
      return;
    }
    google.charts.load(chartVersion, {
      packages: chartPackages,
      language: chartLanguage,
      mapsApiKey,
    });
    google.charts.setOnLoadCallback(() => {
      if (!isGoogleChartsReady(props, google)) {
        const error = new Error(
          "[GoogleChartsInitializationError] Google Charts not ready after load callback.",
        );
        console.error(error);
        setGoogleChartsInitializationError(error);
        return;
      }
      setGoogleCharts(google);
    });
  }, [isSuccess]);
  return {
    error:
      scriptLoadingError ||
      scriptInitializationError ||
      googleChartsInitializationError,
    isLoading,
    google: googleCharts,
  };
}

export interface ILoadGoogleChartsProps extends IUseLoadGoogleChartsParams {
  onLoad?(googleCharts: GoogleViz): void;
  onError?(): void;
}
import { ReactGoogleChartProps } from "./types";

export const chartDefaultProps: Partial<ReactGoogleChartProps> = {
  // <DEPRECATED_PROPS>
  legend_toggle: false,
  // </DEPRECATED_PROPS>
  options: {},
  legendToggle: false,
  getChartWrapper: () => {},
  spreadSheetQueryParameters: {
    headers: 1,
    gid: 1,
  },
  rootProps: {},
  chartWrapperParams: {},
  chartLoaderScriptUrl: "https://www.gstatic.com/charts/loader.js",
};
import React from "react";
import { GoogleChartControlAndProp } from "../hooks/internal/useGoogleChartControls";

export type FilterControl = (control: GoogleChartControlAndProp) => boolean;

type Props = {
  isReady: boolean;
  chartControls: GoogleChartControlAndProp[] | null;
  filter?: FilterControl;
};
export const GoogleChartControls = (props: Props) => {
  const { isReady, chartControls, filter } = props;
  if (!isReady || !chartControls || !chartControls?.length) {
    return null;
  }
  return (
    <>
      {chartControls
        .filter(({ controlProp, control }) => {
          return filter ? filter({ control, controlProp }) : true;
        })
        .map(({ control }) => {
          return (
            <div key={control.getContainerId()} id={control.getContainerId()} />
          );
        })}
    </>
  );
};
let uniqueID = 0;
export const generateUniqueID = () => {
  uniqueID += 1;
  return `reactgooglegraph-${uniqueID}`;
};
import {
  GoogleViz,
  ReactGoogleChartProps,
  GoogleChartControlProp,
  GoogleChartControl,
  UseChartControlsParams,
} from "../types";
import { generateUniqueID } from "../generate-unique-id";

export type Props = ReactGoogleChartProps & {
  google: GoogleViz;
};

export type GoogleChartControlAndProp = {
  controlProp: GoogleChartControlProp;
  control: GoogleChartControl;
};

/**
 * An internal helper class for creating and managing Google Charts controls.
 * Offers high-level methods to interact with the Google Chart Controls.
 */
export class GoogleChartControlsInternal {
  /**
   * Initialize the controls once chart is ready
   */
  private static initializeControls = (
    googleChartControls: GoogleChartControlAndProp[],
  ) => {
    for (let i = 0; i < googleChartControls.length; i += 1) {
      const { controlType, options, controlWrapperParams } =
        googleChartControls[i].controlProp;
      if (controlWrapperParams && "state" in controlWrapperParams) {
        googleChartControls[i].control.setState(controlWrapperParams["state"]);
      }
      googleChartControls[i].control.setOptions(options);
      googleChartControls[i].control.setControlType(controlType);
    }
  };

  /**
   * listen to the control events (ready, statechange, error) specified in the controlEvents prop
   */
  public static listenToControlEvents = (
    googleChartControls: GoogleChartControlAndProp[],
    props: UseChartControlsParams,
  ) => {
    const { google } = props;
    return googleChartControls.flatMap((chartControl) => {
      const { control, controlProp } = chartControl;
      const { controlEvents = [] } = controlProp;
      return controlEvents.map((event) => {
        const { callback, eventName } = event;
        return google.visualization.events.addListener(
          control,
          eventName,
          (...args) => {
            callback({
              chartWrapper: null,
              controlWrapper: control,
              props: props,
              google: google,
              eventArgs: args,
            });
          },
        );
      });
    });
  };

  /**
   * If controlID is not provided, generate a unique controlID
   */
  private static createControlId = (id: undefined | string) => {
    let controlID: string;
    if (typeof id === "undefined") {
      controlID = `googlechart-control-${generateUniqueID()}`;
    } else {
      controlID = id;
    }
    return controlID;
  };

  /**
   * Map the control props to Google Chart Controls
   */
  private static createChartControls = (props: UseChartControlsParams) => {
    const { controls, google } = props;
    if (!controls) {
      return null;
    }

    return controls.map((control, i) => {
      const {
        controlID: controlIDMaybe,
        controlType,
        options: controlOptions,
        controlWrapperParams,
      } = control;
      const controlID = this.createControlId(controlIDMaybe);
      return {
        controlProp: control,
        control: new google.visualization.ControlWrapper({
          containerId: controlID,
          controlType,
          options: controlOptions,
          ...controlWrapperParams,
        }),
      };
    });
  };

  static addControls = (props: UseChartControlsParams) => {
    const { chartWrapper, chartDashboard } = props;
    const googleChartControls = this.createChartControls(props);
    if (!googleChartControls || !chartDashboard || !chartWrapper) {
      return null;
    }
    chartDashboard.bind(
      googleChartControls.map(({ control }) => control),
      chartWrapper,
    );
    this.initializeControls(googleChartControls);
    return googleChartControls;
  };
}
import * as React from "react";
import {
  GoogleViz,
  ReactGoogleChartProps,
  GoogleChartControlProp,
  GoogleChartControl,
  UseChartControlsParams,
} from "../../types";
import {
  FilterControl,
  GoogleChartControls,
} from "../../components/GoogleChartControls";
import { GoogleChartControlsInternal } from "../../utils/GoogleChartControlsInternal";

const useCreateChartControls = (
  controls: ReactGoogleChartProps["controls"],
) => {
  const [chartControls, setChartControls] = React.useState<
    GoogleChartControl[] | null
  >(null);

  const controlAndProp = React.useMemo(() => {
    if (!chartControls || !controls) return null;

    return controls
      .map((controlProp, i): GoogleChartControlAndProp | undefined => {
        const control: GoogleChartControl | undefined = chartControls[i];
        return control ? { controlProp, control } : undefined;
      })
      .flatMap((controlAndProp) => (controlAndProp ? [controlAndProp] : []));
  }, [chartControls, controls]);

  return [controlAndProp, setChartControls] as const;
};

const useListenToControlEvents = (
  chartControls: GoogleChartControlAndProp[],
  props: UseChartControlsParams,
) => {
  React.useEffect(() => {
    const listeners = GoogleChartControlsInternal.listenToControlEvents(
      chartControls ?? [],
      props,
    );

    return () => {
      listeners.forEach((listener) => {
        props.google.visualization.events.removeListener(listener);
      });
    };
  }, [chartControls, props]);
};

export type Props = ReactGoogleChartProps & {
  google: GoogleViz;
};

export type GoogleChartControlAndProp = {
  controlProp: GoogleChartControlProp;
  control: GoogleChartControl;
};

export const useChartControls = (props: UseChartControlsParams) => {
  const [chartControls, setChartControls] = useCreateChartControls(
    props.controls,
  );

  useListenToControlEvents(chartControls ?? [], props);

  /**
   * Render the container divs for the controls
   */
  const renderControl = (filter: FilterControl) => {
    const { chartWrapper, chartDashboard } = props;
    return (
      <GoogleChartControls
        {...props}
        isReady={Boolean(chartWrapper && chartDashboard)}
        chartControls={chartControls}
        filter={filter}
      />
    );
  };

  return {
    addControls: (props: UseChartControlsParams) => {
      const controls = GoogleChartControlsInternal.addControls(props);
      setChartControls(controls?.map((control) => control.control) ?? null);
    },
    renderControl,
  };
};
import * as React from "react";
import { ReactGoogleChartProps } from "../../types";
import { generateUniqueID } from "../../generate-unique-id";

export const useChartId = (
  props: Pick<ReactGoogleChartProps, "graphID" | "graph_id">,
) => {
  const chartIdRef = React.useRef<string | null>(null);
  const getChartId = (): string => {
    const { graphID, graph_id } = props;
    const chartIdFromProps = graphID || graph_id;
    let currentChartId: string;
    if (chartIdFromProps) {
      currentChartId = chartIdFromProps as string;
    } else {
      currentChartId = chartIdRef.current || generateUniqueID();
    }
    chartIdRef.current = currentChartId;
    return chartIdRef.current as string;
  };
  const chartId = getChartId();
  return { chartId };
};
