    if (chartDiff) {
      googleChartWrapper.setDataTable(chartDiff);
      googleChartWrapper.draw();
    }
    if (formatters) {
      this.applyFormatters({ dataTable, formatters, google });
      googleChartWrapper.setDataTable(dataTable);
      googleChartWrapper.draw();
    }
    if (legendToggle === true || legend_toggle === true) {
      this.grayOutHiddenColumnsLabel(props, hiddenColumns);
    }
    return;
  };
  /**
   * Get the column ID of a column in a GoogleDataTable.
   * If the column has an ID, return the ID, otherwise return the label.
   */
  private static getColumnId = (
    dataTable: GoogleDataTable,
    columnIndex: number,
  ) => {
    return (
      dataTable.getColumnId(columnIndex) ||
      dataTable.getColumnLabel(columnIndex)
    );
  };

  /**
   * Apply Chart Formatters passed under the formatters prop to the GoogleDataTable
   */
  private static applyFormatters = ({
    dataTable,
    formatters,
    google,
  }: ApplyFormattersParams) => {
    for (let formatter of formatters) {
      switch (formatter.type) {
        case "ArrowFormat": {
          const vizFormatter = new google.visualization.ArrowFormat(
            formatter.options,
          );
          vizFormatter.format(dataTable, formatter.column);
          return;
        }
        case "BarFormat": {
          const vizFormatter = new google.visualization.BarFormat(
            formatter.options,
          );
          vizFormatter.format(dataTable, formatter.column);
          return;
        }
        case "ColorFormat": {
          const vizFormatter = new google.visualization.ColorFormat(
            formatter.options,
          );
          const { ranges } = formatter;
          if (ranges) {
            for (let range of ranges) {
              vizFormatter.addRange(...range);
            }
          }
          vizFormatter.format(dataTable, formatter.column);
          return;
        }
        case "DateFormat": {
          const vizFormatter = new google.visualization.DateFormat(
            formatter.options,
          );
          vizFormatter.format(dataTable, formatter.column);
          return;
        }
        case "NumberFormat": {
          const vizFormatter = new google.visualization.NumberFormat(
            formatter.options,
          );
          vizFormatter.format(dataTable, formatter.column);
          return;
        }
        case "PatternFormat": {
          const vizFormatter = new google.visualization.PatternFormat(
            formatter.options,
          );
          vizFormatter.format(dataTable, formatter.column);
          return;
        }
        default: {
          console.warn(`Unknown formatter type: ${formatter.type}`);
          return;
        }
      }
    }
  };
}
import * as React from "react";
import {
  GoogleViz,
  GoogleChartWrapper,
  ReactGoogleChartProps,
  GoogleChartDashboard,
  GoogleVizEventListener,
} from "../../types";
import { GoogleChartInternal } from "../../utils";

export type ChartDrawArgs = {
  data: ReactGoogleChartProps["data"];
};

export type UseGoogleChartDataTableParams = ReactGoogleChartProps & {
  googleChartWrapper?: GoogleChartWrapper | null;
  google: GoogleViz;
  googleChartDashboard?: GoogleChartDashboard | null;
};

export const useGoogleChartDataTable = (
  props: UseGoogleChartDataTableParams,
) => {
  const { google, googleChartWrapper, googleChartDashboard } = props;
  const [hiddenColumns, setHiddenColumns] = React.useState<string[]>([]);
  // Re-draw the chart when hiddenColumns change
  React.useEffect(() => {
    if (!googleChartWrapper) {
      return;
    }
    GoogleChartInternal.draw({
      ...props,
      hiddenColumns,
      googleChartWrapper,
      googleChartDashboard,
      google,
    });
  }, [
    hiddenColumns,
    props.data,
    props.rows,
    props.columns,
    props.options,
    props.chartLoaderScriptUrl,
    props.chartType,
    props.formatters,
    props.spreadSheetUrl,
    props.spreadSheetQueryParameters,
    props.legendToggle,
    props.legend_toggle,
  ]);

  // Re-draw the chart when the window is resized
  const onResize = () => {
    const { googleChartWrapper } = props;
    if (!googleChartWrapper) {
      return;
    }
    googleChartWrapper.draw();
  };

  // Draw the chart when the google charts wrapper is ready and when the hiddenColumns change
  const initialize = (googleChartWrapper: GoogleChartWrapper) => {
    const listeners: GoogleVizEventListener[] = [];

    const { legendToggle, legend_toggle } = props;
    GoogleChartInternal.draw({
      ...props,
      hiddenColumns,
      googleChartWrapper,
      googleChartDashboard,
      google,
    });
    window.addEventListener("resize", onResize);
    if (legend_toggle || legendToggle) {
      const listener = GoogleChartInternal.listenToLegendToggle(props, [
        hiddenColumns,
        setHiddenColumns,
      ]);

      if (listener) listeners.push(listener);
    }

    return listeners;
  };

  // Remove event listeners and clear the chart when the component is unmounted
  const destroy = (
    googleChartWrapper: GoogleChartWrapper,
    listeners: GoogleVizEventListener[],
  ) => {
    window.removeEventListener("resize", onResize);
    listeners.forEach((listener) => {
      google.visualization.events.removeListener(listener);
    });
    if (googleChartWrapper.getChartType() === "Timeline") {
      googleChartWrapper.getChart() &&
        googleChartWrapper.getChart().clearChart();
    }
  };

  React.useEffect(() => {
    if (!googleChartWrapper) {
      return;
    }
    const listeners = initialize(googleChartWrapper);
    return () => {
      destroy(googleChartWrapper, listeners);
    };
  }, [googleChartWrapper, initialize, destroy]);
};
import { useEffect } from "react";
import {
  GoogleChartWrapper,
  GoogleViz,
  ReactGoogleChartProps,
} from "../../types";

export type GoogleChartEventsParams = ReactGoogleChartProps & {
  googleChartWrapper?: GoogleChartWrapper | null;
  google: GoogleViz;
};

const listenToEvents = (props: GoogleChartEventsParams) => {
  const { chartEvents, google, googleChartWrapper } = props;
  if (!chartEvents) {
    return;
  }
  if (!googleChartWrapper) {
    console.warn("listenToEvents was called before chart wrapper ready.");
    return;
  }
  return chartEvents.map(({ eventName, callback }) => {
    return google.visualization.events.addListener(
      googleChartWrapper,
      eventName,
      (...args) => {
        callback({
          chartWrapper: googleChartWrapper,
          props,
          google: google,
          eventArgs: args,
        });
      },
    );
  });
};

export const useGoogleChartEvents = (props: GoogleChartEventsParams) => {
  useEffect(() => {
    if (!props.googleChartWrapper) return;

    const listeners = listenToEvents(props);

    return () => {
      listeners?.forEach((listener) => {
        props.google.visualization.events.removeListener(listener);
      });
    };
  }, [props]);
};
import * as React from "react";
import {
  GoogleViz,
  GoogleChartWrapper,
  ReactGoogleChartProps,
  GoogleChartDashboard,
  GoogleChartEditor,
} from "../types";
import { useChartControls } from "../hooks/internal/useGoogleChartControls";
import { useChartId } from "../hooks/internal/useChartId";
import { useGoogleChartDataTable } from "../hooks/internal/useGoogleChartDataTable";
import { useGoogleChartEvents } from "../hooks/internal/useGoogleChartEvents";

type Props = ReactGoogleChartProps & {
  google: GoogleViz;
};

export const GoogleChart: React.FC<Props> = (props) => {
  const [googleChartWrapper, setGoogleChartWrapper] =
    React.useState<GoogleChartWrapper | null>(null);
  // const [isReady, setIsReady] = React.useState<boolean>(false);
  const [googleChartDashboard, setGoogleChartDashboard] =
    React.useState<GoogleChartDashboard | null>(null);

  const { addControls, renderControl } = useChartControls({
    ...props,
    chartDashboard: googleChartDashboard,
    chartWrapper: googleChartWrapper,
  });
  useGoogleChartEvents({
    ...props,
    googleChartWrapper,
  });
  const { chartId } = useChartId(props);
  const dashboardRef = React.useRef<HTMLDivElement>(null);
  const toolbarRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const {
      options,
      google,
      chartType,
      chartWrapperParams,
      toolbarItems,
      getChartEditor,
      getChartWrapper,
      onLoad,
    } = props;

    const chartConfig = {
      chartType,
      options,
      containerId: chartId,
      ...chartWrapperParams,
    };
    // Create ChartWrapper instance, pass it to the user and store it in state
    const chartWrapper = new google.visualization.ChartWrapper(chartConfig);
    chartWrapper.setOptions(options || {});
    getChartWrapper?.(chartWrapper, google);

    // Create Dashboard instance, needed for controls
    const chartDashboard = new google.visualization.Dashboard(
      dashboardRef.current,
    );

    // Create toolbar if needed
    if (toolbarItems) {
      google.visualization.drawToolbar(
        toolbarRef.current as HTMLDivElement,
        toolbarItems,
      );
    }

    // Create ChartEditor instance if needed and pass it to the user
    let chartEditor: GoogleChartEditor | null = null;
    if (getChartEditor) {
      chartEditor = new google.visualization.ChartEditor();
      getChartEditor({
        chartEditor,
        chartWrapper,
        google,
      });
    }
    // Create and add controls to the chart / dashboard
    addControls({ ...props, chartDashboard, chartWrapper });
    setGoogleChartWrapper(chartWrapper);
    setGoogleChartDashboard(chartDashboard);
    onLoad?.(google, {
      google,
      chartWrapper,
      chartEditor,
      chartDashboard,
    });
  }, []);

  useGoogleChartDataTable({
    ...props,
    googleChartWrapper,
    googleChartDashboard,
  });
  const renderChart = () => {
    const { width, height, options, style, className, rootProps, google } =
      props;

    const divStyle = {
      height: height || (options && options.height),
      width: width || (options && options.width),
      ...style,
    };
    return (
      <div id={chartId} style={divStyle} className={className} {...rootProps} />
    );
  };

  const renderToolBar = () => {
    if (!props.toolbarItems) return null;
    return <div ref={toolbarRef} />;
  };

  const { width, height, options, style } = props;

  const divStyle = {
    height: height || (options && options.height),
    width: width || (options && options.width),
    ...style,
  };

  // If render prop is provided, give the user full control over the rendering by passing renderChart, renderControl and renderToolbar functions
  if (props.render) {
    return (
      <div ref={dashboardRef} style={divStyle}>
        <div ref={toolbarRef} id="toolbar" />
        {props.render({
          renderChart,
          renderControl,
          renderToolbar: renderToolBar,
        })}
      </div>
    );
  } else {
    return (
      <div ref={dashboardRef} style={divStyle}>
        {renderControl(
          ({ controlProp }) => controlProp.controlPosition !== "bottom",
        )}
        {renderChart()}
        {renderControl(
          ({ controlProp }) => controlProp.controlPosition === "bottom",
        )}
        {renderToolBar()}
      </div>
    );
  }
};

export default GoogleChart;
